script:
/* CEO agent (وكيل الرئيس التنفيذي). Paste into a Frappe Custom HTML Block's Script field; leave the HTML field empty. */
/* Generated by build_agent_blocks.py from ai-chat.js. Edit the template, not this copy. */
/* global frappe, root_element */
;(() => {
  "use strict"
  /* Phase 1 runs through the durar_ai_relay Server Script, which refuses approvals.
     Actions also need the ceopanel_bridge app: install it, then set the method to
     ceopanel_bridge.ai_relay.request and READ_ONLY to false. */
  const RELAY_METHOD = "durar_ai_relay"
  const READ_ONLY = true
  /* durar:agent-config:start */
  const AGENT = "ceo"
  /* durar:agent-config:end */
  const ALL_COMPANIES = "__all_companies__"
  const host = typeof root_element !== "undefined" ? root_element : null
  if (!host) return
  host.__durarDestroy?.()
  const previous = host.querySelector(".durar-ai")
  previous?.remove()
  const ar = (frappe.boot?.lang || document.documentElement.lang).startsWith(
    "ar"
  )
  const t = (en, arabic) => (ar ? arabic : en)
  const AGENT_LABELS = {
    ceo: ["CEO agent", "وكيل الرئيس التنفيذي"],
    executive: ["Executive agent", "الوكيل التنفيذي"],
    finance: ["Finance agent", "وكيل المالية"],
    sales: ["Sales agent", "وكيل المبيعات"],
    operations: ["Operations agent", "وكيل العمليات"],
    support: ["Support agent", "وكيل الدعم"],
  }
  const agentLabel = (id) =>
    AGENT_LABELS[id] ? t(...AGENT_LABELS[id]) : t("AI agent", "وكيل ذكي")
  let company,
    chat,
    activeRun,
    agentId,
    cursor = 0,
    generation = 0,
    stopped = false,
    timer,
    pdfUrl
  let uploads = [],
    submitting = false,
    pending,
    history = [],
    chatRows = [],
    chatMore = null,
    liveSteps = new Map(),
    liveRow = null,
    pollFailures = 0
  const draftKey = () =>
    `durar-ai:draft:${location.origin}:${frappe.session.user}:${company || ""}:${chat?.id || "new"}`
  const storage = {
    get: () => {
      try {
        return JSON.parse(localStorage.getItem(draftKey()) || "{}")
      } catch {
        return {}
      }
    },
    put: (value) => {
      try {
        localStorage.setItem(
          draftKey(),
          JSON.stringify({ ...value, savedAt: Date.now() })
        )
      } catch {
        /* optional drafts */
      }
    },
    clear: () => {
      try {
        localStorage.removeItem(draftKey())
      } catch {
        /* optional drafts */
      }
    },
  }
  const themeKey = `durar-ai:theme:${frappe.session.user}`
  function savedTheme() {
    try {
      return localStorage.getItem(themeKey)
    } catch {
      return null
    }
  }
  const ICONS = {
    plus: '<path d="M12 5v14M5 12h14"/>',
    edit: '<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/>',
    search: '<circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/>',
    sidebar: '<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16"/>',
    moon: '<path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/>',
    sun: '<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
    up: '<path d="M12 19V5M5 12l7-7 7 7"/>',
    stop: '<rect x="6" y="6" width="12" height="12" rx="2.5" fill="currentColor"/>',
    shield:
      '<path d="M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6z"/><path d="m9 12 2 2 4-4"/>',
    copy: '<rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h8"/>',
    refresh: '<path d="M21 12a9 9 0 1 1-3-6.7L21 8M21 3v5h-5"/>',
    trash: '<path d="M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14"/>',
    x: '<path d="M6 6l12 12M18 6 6 18"/>',
    file: '<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/>',
    check: '<path d="m5 12 5 5L20 7"/>',
    alert: '<path d="M12 3 2 21h20z"/><path d="M12 10v5M12 18h.01"/>',
    memory: '<path d="M12 3a9 9 0 1 0 9 9"/><path d="M12 7v5l3 2"/>',
    ext: '<path d="M14 4h6v6M20 4 10 14M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5"/>',
    download: '<path d="M12 4v11M7 11l5 5 5-5M4 20h16"/>',
    spin: '<path d="M21 12a9 9 0 1 1-6.2-8.6"/>',
    arrowdown: '<path d="M12 5v14M5 12l7 7 7-7"/>',
    thumbup:
      '<path d="M7 11v9H4v-9zM7 11l4-8a2 2 0 0 1 2 2v4h6a2 2 0 0 1 2 2l-1 7a2 2 0 0 1-2 2H7"/>',
    thumbdown:
      '<path d="M7 13V4H4v9zM7 13l4 8a2 2 0 0 0 2-2v-4h6a2 2 0 0 0 2-2l-1-7a2 2 0 0 0-2-2H7"/>',
  }
  const svg = (name) =>
    `<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]}</svg>`
  const SUGGESTIONS = {
    ceo: [
      ["Give me a company-wide summary for this month", "أعطني ملخصًا عن الشركة لهذا الشهر"],
      ["Show unpaid invoices for this month", "اعرض الفواتير غير المدفوعة لهذا الشهر"],
      ["Prepare a PDF report of this month's sales", "جهّز تقريرًا بصيغة PDF عن مبيعات هذا الشهر"],
    ],
    executive: [
      ["Summarise this month's KPIs", "لخّص مؤشرات الأداء لهذا الشهر"],
      ["Compare sales this month vs last month", "قارن مبيعات هذا الشهر بالشهر الماضي"],
      ["Give me this month's KPIs as a PDF", "أعطني مؤشرات هذا الشهر بصيغة PDF"],
    ],
    finance: [
      ["Show unpaid invoices for this month", "اعرض الفواتير غير المدفوعة لهذا الشهر"],
      ["List payments received this week", "اعرض المدفوعات المستلمة هذا الأسبوع"],
      ["Prepare a PDF of the receivables report", "جهّز تقرير الذمم المدينة بصيغة PDF"],
    ],
    sales: [
      ["Show open leads for this week", "اعرض العملاء المحتملين المفتوحين هذا الأسبوع"],
      ["List quotations awaiting follow-up", "اعرض عروض الأسعار التي تنتظر المتابعة"],
    ],
    operations: [
      ["List pending sales orders", "اعرض أوامر البيع المعلقة"],
      ["Which vehicle documents expire soon?", "ما مستندات المركبات التي تنتهي قريبًا؟"],
    ],
    support: [
      ["Show open customer queries", "اعرض استفسارات العملاء المفتوحة"],
      ["List tickets older than 3 days", "اعرض التذاكر الأقدم من ٣ أيام"],
    ],
  }
  const AGENT_TAGS = {
    ceo: ["Strategic insights across departments", "رؤى استراتيجية عبر الإدارات"],
    executive: ["KPIs, reports and summaries", "المؤشرات والتقارير والملخصات"],
    finance: ["Invoices, payments and reminders", "الفواتير والمدفوعات والتذكيرات"],
    sales: ["Leads, quotations and follow-ups", "العملاء المحتملون والعروض والمتابعات"],
    operations: ["Orders, stock and vehicles", "الطلبات والمخزون والمركبات"],
    support: ["Customer queries and tickets", "استفسارات العملاء والتذاكر"],
  }
  function el(tag, className, text) {
    const node = document.createElement(tag)
    if (className) node.className = className
    if (text !== undefined) node.textContent = text
    return node
  }
  function button(text, action, parent, className = "") {
    const node = el("button", className, text)
    node.type = "button"
    node.addEventListener("click", async () => {
      node.disabled = true
      try {
        await action()
      } catch (error) {
        showError(error)
      } finally {
        if (node.isConnected) node.disabled = false
      }
    })
    parent?.append(node)
    return node
  }
  function iconButton(icon, label, action, parent, className = "") {
    const node = button("", action, parent, `durar-ai-icon ${className}`)
    node.innerHTML = svg(icon)
    node.title = label
    node.setAttribute("aria-label", label)
    return node
  }
  function labelled(icon, text, action, parent, className) {
    const node = button("", action, parent, className)
    node.innerHTML = svg(icon)
    node.append(el("span", "", text))
    return node
  }
  /* Resolves to null when dismissed; Cancel comes first so it takes initial focus. */
  function ask({ heading, body, details, confirm, danger, field, maxLength, multiline }) {
    return new Promise((resolve) => {
      const dialog = el("dialog", "durar-ai durar-ai-dialog")
      dialog.dir = app.dir
      dialog.dataset.theme = app.dataset.theme
      const titleNode = el("h2", "", heading)
      titleNode.id = `dialog-${crypto.randomUUID()}`
      dialog.setAttribute("aria-labelledby", titleNode.id)
      dialog.append(titleNode)
      if (body) dialog.append(el("p", "", body))
      if (details) dialog.append(details)
      const row = el("form", "durar-ai-dialog-actions")
      let textField = null
      if (field !== undefined) {
        textField = el(multiline ? "textarea" : "input", "durar-ai-input")
        if (multiline) textField.rows = 8
        textField.value = field
        textField.maxLength = maxLength || 120
        textField.setAttribute("aria-label", heading)
        textField.addEventListener("keydown", (event) => {
          if (event.key === "Enter" && !multiline) {
            event.preventDefault()
            row.requestSubmit()
          }
        })
        dialog.append(textField)
      }
      let result = null
      const cancel = el("button", "durar-ai-pill", t("Cancel", "إلغاء"))
      cancel.type = "button"
      cancel.addEventListener("click", () => dialog.close())
      const accept = el(
        "button",
        `durar-ai-pill ${danger ? "durar-ai-danger" : "durar-ai-solid"}`,
        confirm
      )
      accept.type = "submit"
      row.addEventListener("submit", (event) => {
        event.preventDefault()
        if (textField && !textField.value.trim()) return
        result = textField ? textField.value.trim() : true
        dialog.close()
      })
      row.append(cancel, accept)
      dialog.append(row)
      dialog.addEventListener(
        "close",
        () => {
          dialog.remove()
          resolve(result)
        },
        { once: true }
      )
      app.append(dialog)
      dialog.showModal()
      textField?.select()
    })
  }
  function toast(text, kind = "") {
    const node = el("div", `durar-ai-toast ${kind}`, text)
    node.setAttribute("role", "status")
    app.append(node)
    setTimeout(() => node.remove(), 3200)
  }
  // Nothing but bootstrap may run until Durar has confirmed this block's agent.
  // Without this a stale relay could answer as another department's agent.
  let ready = false
  let notReady = ""
  const gated = []
  // Frappe rejects with its XHR object. The server's own sentence is the useful
  // part, so pull it out instead of showing "Request failed".
  function readableError(error) {
    if (error instanceof Error && error.message) return error.message
    const body = error?.responseJSON
    try {
      const list = body?._server_messages ? JSON.parse(body._server_messages) : []
      const text = list.length ? JSON.parse(list[0]).message : ""
      if (text) return String(text).replace(/<[^>]*>/g, "").slice(0, 300)
    } catch {
      /* fall through to the exception line */
    }
    const detail = String(body?.exception || "").split(": ").slice(1).join(": ")
    return detail.slice(0, 300)
  }
  async function api(operation, data = {}) {
    if (!ready && operation !== "bootstrap")
      throw new Error(
        notReady || t("This block is still starting.", "الكتلة قيد البدء.")
      )
    let result
    try {
      result = await frappe.call({
        method: RELAY_METHOD,
        type: "POST",
        args: {
          operation,
          data: JSON.stringify(data),
          company,
          ...(AGENT ? { agent: AGENT } : {}),
        },
      })
    } catch (error) {
      throw Object.assign(new Error(
        readableError(error) ||
          t(
            "Could not reach Durar. Check your connection and try again.",
            "تعذر الوصول إلى درر. تحقق من الاتصال وحاول مجدداً."
          )
      ), { transient: (!error?.responseJSON && [0, 408, 500, 502, 503, 504].includes(Number(error?.status || 0))) || /^AI backend is unavailable\./i.test(readableError(error)) })
    }
    if (!result.message || result.exc)
      throw new Error(t("AI request failed", "تعذر إكمال الطلب"))
    return result.message
  }

  /* Escapes everything first; only the tags built here can reach innerHTML. */
  const esc = (s) =>
    String(s).replace(
      /[&<>"']/g,
      (c) =>
        ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]
    )
  function inline(text) {
    const codes = []
    return esc(text)
      .replace(/`([^`\n]+)`/g, (_, c) => {
        codes.push(c)
        return `\u0000${codes.length - 1}\u0000`
      })
      .replace(/\*\*([^*\n]+)\*\*/g, "<strong>$1</strong>")
      .replace(/(^|[^*])\*([^*\n]+)\*/g, "$1<em>$2</em>")
      .replace(/~~([^~\n]+)~~/g, "<del>$1</del>")
      .replace(/\[([^\]]+)\]\(\/api\/erp\/files\?id=([a-f0-9-]{36})\)/gi,
        '<a href="#" data-download-id="$2">$1</a>')
      .replace(
        /\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
        '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>'
      )
      .replace(/\u0000(\d+)\u0000/g, (_, i) => `<code>${codes[i] ?? ""}</code>`)
  }
  const LIST_ITEM = /^\s*([-*]|\d+\.)\s+/
  function markdown(source) {
    const lines = String(source).replace(/\r/g, "").split("\n")
    let out = "",
      i = 0
    while (i < lines.length) {
      const line = lines[i]
      let match
      if ((match = line.match(/^```(\w*)/))) {
        const code = []
        i++
        while (i < lines.length && !lines[i].startsWith("```"))
          code.push(lines[i++])
        i++
        out += `<div class="durar-ai-code"><div class="durar-ai-code-head"><span>${esc(match[1] || "code")}</span><button type="button" data-copy>${esc(t("Copy", "نسخ"))}</button></div><pre><code>${esc(code.join("\n"))}</code></pre></div>`
      } else if ((match = line.match(/^(#{1,3})\s+(.*)/))) {
        out += `<h${match[1].length}>${inline(match[2])}</h${match[1].length}>`
        i++
      } else if (/^---+$/.test(line.trim())) {
        out += "<hr>"
        i++
      } else if (/^>\s?/.test(line)) {
        const quote = []
        while (i < lines.length && /^>\s?/.test(lines[i]))
          quote.push(lines[i++].replace(/^>\s?/, ""))
        out += `<blockquote>${inline(quote.join(" "))}</blockquote>`
      } else if (LIST_ITEM.test(line)) {
        const tag = /^\s*\d+\./.test(line) ? "ol" : "ul",
          items = []
        while (i < lines.length && LIST_ITEM.test(lines[i]))
          items.push(`<li>${inline(lines[i++].replace(LIST_ITEM, ""))}</li>`)
        out += `<${tag}>${items.join("")}</${tag}>`
      } else if (
        line.includes("|") &&
        /^\s*\|?[\s:-]+\|[\s|:-]*$/.test(lines[i + 1] || "")
      ) {
        const cells = (row) =>
          row
            .trim()
            .replace(/^\||\|$/g, "")
            .split("|")
            .map((c) => inline(c.trim()))
        const head = cells(line),
          rows = []
        i += 2
        while (i < lines.length && lines[i].includes("|"))
          rows.push(cells(lines[i++]))
        out += `<table><thead><tr>${head.map((c) => `<th>${c}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`
      } else if (!line.trim()) i++
      else {
        const text = []
        while (
          i < lines.length &&
          lines[i].trim() &&
          !/^(```|#{1,3}\s|>|\s*([-*]|\d+\.)\s)/.test(lines[i])
        )
          text.push(lines[i++])
        out += `<p>${inline(text.join("\n")).replace(/\n/g, "<br>")}</p>`
      }
    }
    return out
  }

  const app = el("section", "durar-ai")
  app.dir = ar ? "rtl" : "ltr"
  app.setAttribute("aria-label", agentLabel(AGENT))
  function applyTheme(theme) {
    app.dataset.theme = theme
    themeToggle.innerHTML = svg(theme === "dark" ? "sun" : "moon")
  }

  const sidebar = el("aside", "durar-ai-sidebar")
  const sideTop = el("div", "durar-ai-side-top")
  const brand = el("span", "durar-ai-brand", agentLabel(AGENT))
  sideTop.append(brand)
  const toggleSidebar = () => setSidebarCollapsed(!sidebar.classList.contains("collapsed"))
  function setSidebarCollapsed(collapsed) {
    sidebar.classList.toggle("collapsed", collapsed)
    topbarSidebar.hidden = !collapsed
    topbarSidebar.setAttribute("aria-expanded", String(!collapsed))
  }
  iconButton(
    "sidebar",
    t("Close sidebar", "إغلاق الشريط الجانبي"),
    toggleSidebar,
    sideTop
  )
  sidebar.append(sideTop)
  gated.push(
    labelled(
      "edit",
      t("+ New chat", "+ محادثة جديدة"),
      newChat,
      sidebar,
      "durar-ai-side-item"
    )
  )
  const searchBox = el("label", "durar-ai-side-item")
  searchBox.innerHTML = svg("search")
  const search = el("input")
  search.type = "search"
  search.autocomplete = "off"
  search.placeholder = t("Search loaded chats", "ابحث في المحادثات المحمّلة")
  search.setAttribute("aria-label", search.placeholder)
  search.addEventListener("input", renderChats)
  searchBox.append(search)
  sidebar.append(searchBox)
  const chatList = el("nav")
  chatList.setAttribute("aria-label", t("Your chats", "محادثاتك"))
  sidebar.append(chatList)
  const sideFoot = el("div", "durar-ai-side-foot")
  gated.push(
    labelled("memory", t("Memory", "الذاكرة"), memory, sideFoot, "durar-ai-side-item")
  )
  labelled(
    "refresh",
    t("Reload", "إعادة تحميل"),
    async () => {
      if (!ready) return start()
      if (chat) await load(chat.id)
      else await list()
    },
    sideFoot,
    "durar-ai-side-item"
  )
  const userCard = el("div", "durar-ai-user-card")
  const userName = String(
    frappe.session.user_fullname || frappe.session.user || ""
  )
  userCard.append(
    el("span", "durar-ai-avatar", userName.charAt(0).toUpperCase()),
    el("span", "durar-ai-user-name", userName)
  )
  sideFoot.append(userCard)
  sidebar.append(sideFoot)

  const main = el("div", "durar-ai-main")
  const topbar = el("header", "durar-ai-topbar")
  const topbarSidebar = iconButton(
    "sidebar",
    t("Toggle sidebar", "إظهار الشريط الجانبي"),
    toggleSidebar,
    topbar
  )
  topbarSidebar.hidden = true
  const title = el("h2", "", t("New chat", "محادثة جديدة"))
  const agent = el("span", "durar-ai-agent")
  topbar.append(title, agent, el("span", "durar-ai-spacer"))
  const pendingBadge = el("span", "durar-ai-pending")
  pendingBadge.hidden = true
  topbar.append(pendingBadge)
  // A spinning wheel while a coordination task this chat started is running.
  const workingBadge = el("span", "durar-ai-working")
  workingBadge.hidden = true
  topbar.append(workingBadge)
  iconButton("download", t("Export chat", "تصدير المحادثة"), exportChat, topbar)
  const companies = el("select")
  companies.setAttribute("aria-label", t("Company", "الشركة"))
  topbar.append(companies)
  const themeToggle = iconButton(
    "moon",
    t("Toggle theme", "تبديل المظهر"),
    () => {
      const theme = app.dataset.theme === "dark" ? "light" : "dark"
      applyTheme(theme)
      try {
        localStorage.setItem(themeKey, theme)
      } catch {
        /* optional preference */
      }
    },
    topbar
  )
  const messages = el("div", "durar-ai-messages")
  messages.setAttribute("role", "log")
  messages.setAttribute("aria-live", "polite")
  messages.tabIndex = 0
  messages.addEventListener("click", async (event) => {
    const fileLink = event.target.closest?.("[data-download-id]")
    if (fileLink) {
      event.preventDefault()
      try { await download(fileLink.dataset.downloadId) } catch(error) { showError(error) }
      return
    }
    const copy = event.target.closest?.("[data-copy]")
    if (!copy) return
    try {
      await navigator.clipboard.writeText(
        copy.closest(".durar-ai-code").querySelector("code").textContent
      )
      notice.textContent = t("Copied.", "تم النسخ.")
    } catch (error) {
      showError(error)
    }
  })
  messages.addEventListener("scroll", updateJump)

  const composerWrap = el("div", "durar-ai-composer-wrap")
  const jump = iconButton(
    "arrowdown",
    t("Scroll to latest", "الانتقال إلى الأحدث"),
    () => {
      messages.scrollTop = messages.scrollHeight
    },
    composerWrap,
    "durar-ai-jump"
  )
  jump.hidden = true
  const notice = el("p", "durar-ai-notice")
  notice.setAttribute("role", "status")
  const form = el("form", "durar-ai-composer")
  const attachments = el("div", "durar-ai-attachments")
  const composerMain = el("div", "durar-ai-composer-main")
  const files = el("input")
  files.type = "file"
  files.multiple = true
  files.hidden = true
  files.accept =
    ".pdf,.txt,.md,.csv,.tsv,.json,.xlsx,.docx,.png,.jpg,.jpeg,.webp"
  gated.push(
    iconButton(
      "plus",
      t("Attach files", "إرفاق ملفات"),
      () => files.click(),
      composerMain
    )
  )
  const input = el("textarea")
  input.rows = 1
  input.dir = "auto"
  input.maxLength = 12000
  input.placeholder = t("Ask about your ERP data…", "اسأل عن بيانات النظام…")
