    )
    const day = 86400000,
      now = Date.now()
    const age = (item) => now - new Date(item.updated_at).getTime()
    const groups = [
      [t("Today", "اليوم"), (item) => age(item) < day],
      [
        t("Previous 7 days", "آخر ٧ أيام"),
        (item) => age(item) >= day && age(item) < 7 * day,
      ],
      [t("Older", "أقدم"), (item) => !(age(item) < 7 * day)],
    ]
    chatList.replaceChildren()
    for (const [label, matches] of groups) {
