  async function openPdf(doctype, name) {
    const query = new URLSearchParams({
      doctype,
      name,
      format: "Standard",
      no_letterhead: "0",
    })
    // ERP's print API decides access using the employee's own session.
    const response = await fetch(
      `/api/method/frappe.utils.print_format.download_pdf?${query}`,
      { credentials: "same-origin" }
    )
    if (!response.ok)
      throw new Error(t("Could not open this PDF.", "تعذر فتح ملف PDF."))
    closePdf()
    pdfUrl = URL.createObjectURL(
      new Blob([await response.blob()], { type: "application/pdf" })
    )
    pdfTitle.textContent = name
    pdfFrame.src = pdfUrl
    pdfPanel.hidden = false
