            `${t("Follow-ups sent", "المتابعات المرسلة")}: ${c.followups || 0}` +
              (next && !Number.isNaN(next.getTime())
                ? ` · ${t("Next check", "الفحص التالي")}: ${next.toLocaleString()}`
                : "")
          )
