  function sources(row, evidence) {
    const box = el("div", "durar-ai-files")
    for (const item of evidence || []) {
      if (!item || typeof item !== "object") continue
      if (item.inherited) continue
      const doctype =
        item.doctype || (item.type === "document" ? item.source : null)
      const name =
        item.name || (item.names?.length === 1 ? item.names[0] : null)
      if (doctype && typeof name === "string") {
        labelled(
          "ext",
          `${doctype} · ${name}`,
          () => frappe.set_route("Form", doctype, name),
          box,
          "durar-ai-card"
        )
        labelled(
          "file",
          t("Open PDF", "فتح PDF"),
          () => openPdf(doctype, name),
          box,
          "durar-ai-card"
        )
      }
      const url = item.file?.downloadUrl
      if (typeof url === "string") {
        const parsed = new URL(url, location.origin),
          id = parsed.searchParams.get("id")
        // Only this site's own file route: the id is all that is ever sent.
        if (
          parsed.origin === location.origin &&
          parsed.pathname === "/api/erp/files" &&
          /^[a-f0-9-]{36}$/i.test(id || "")
        ) {
          labelled(
            "download",
            item.file.name || t("Download", "تحميل"),
            () => download(id),
            box,
            "durar-ai-card"
          )
          if (/^image\/(png|jpeg|gif|webp)$/i.test(item.file.mimeType || ""))
            labelled("file", t("View image", "عرض الصورة"), () => previewImage(id), box, "durar-ai-card")
        }
      }
    }
    if (box.children.length) row.append(box)
  }
  async function download(id, operation = "files.download") {
    const result = await fetchFile(id, operation)
    const bytes = Uint8Array.from(atob(result.base64), (c) => c.charCodeAt(0))
    const url = URL.createObjectURL(new Blob([bytes], { type: result.mime }))
    const link = el("a")
    link.href = url
    link.download = result.name
    link.click()
    setTimeout(() => URL.revokeObjectURL(url), 10000)
  }
  async function fetchFile(id, operation = "files.download") {
    const chatId = chat?.id
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const result = await api(operation, { chatId, id })
        notice.textContent = ""
        delete notice.dataset.kind
        return result
      } catch (error) {
        if (attempt || !error.transient) throw error
        notice.textContent = t("Connection interrupted. Retrying download…", "انقطع الاتصال. جارٍ إعادة محاولة التنزيل…")
        await new Promise(resolve => setTimeout(resolve, 700))
        if (stopped || chat?.id !== chatId) throw error
      }
    }
  }
  async function previewImage(id) {
    const result = await fetchFile(id)
    if (!/^image\/(png|jpeg|gif|webp)$/i.test(result.mime || ""))
      throw new Error(t("This file is not a supported image.", "هذا الملف ليس صورة مدعومة."))
    const bytes = Uint8Array.from(atob(result.base64), c => c.charCodeAt(0))
    const url = URL.createObjectURL(new Blob([bytes], {type:result.mime}))
    const dialog = el("dialog", "durar-ai durar-ai-dialog")
    dialog.dir = app.dir
    dialog.dataset.theme = app.dataset.theme
    dialog.setAttribute("aria-label", result.name)
    const picture = el("img")
    picture.src = url
    picture.alt = result.name
    picture.style.maxWidth = "100%"
    picture.style.maxHeight = "70vh"
    dialog.append(el("h2", "", result.name), picture)
    button(t("Close", "إغلاق"), () => dialog.close(), dialog, "durar-ai-pill")
    dialog.addEventListener("close", () => { URL.revokeObjectURL(url); dialog.remove() }, {once:true})
    app.append(dialog)
    dialog.showModal()
  }
