  function proposalDetails(proposal) {
    const preview = proposal.preview || {}
    const action = preview.action || {}
    if (Array.isArray(preview.changes) && preview.changes.length)
      return changesTable(
        preview.changes.map((c) => [c.field, c.old, c.new]),
        [t("Field", "الحقل"), t("Current", "الحالي"), t("New", "الجديد")]
      )
    if (action.kind === "create" && action.values)
      return changesTable(Object.entries(action.values), [
        t("Field", "الحقل"),
        t("Value", "القيمة"),
      ])
    return el("pre", "", JSON.stringify(preview, null, 2))
  }
  function proposalHeading(proposal) {
