    const target = [action.module, action.name].filter(Boolean).join(" · ")
    const name =
      action.kind === "update"
        ? t("Update", "تعديل")
        : action.kind === "create"
          ? t("Create", "إنشاء")
          : action.kind === "message"
            ? t("Send WhatsApp", "إرسال واتساب")
            : t("Proposed action", "إجراء مقترح")
    return target ? `${name}: ${target}` : name
