  async function decide(proposal, decision) {
    const approving = decision === "approve"
    const confirmed = await ask({
      heading: proposalHeading(proposal),
      body: approving
        ? t(
            "This runs now under your ERP permissions and is recorded in the audit log.",
            "سيُنفَّذ هذا الآن بصلاحياتك في النظام ويُسجَّل في سجل التدقيق."
          )
        : t("Nothing will be changed.", "لن يتم تغيير أي شيء."),
      details: approving ? proposalDetails(proposal) : null,
