        : t("Reject action", "رفض الإجراء"),
      danger: !approving,
    })
    if (!confirmed) return
    const result = await api("approvals.decide", {
      chatId: chat.id,
      approvalId: proposal.id,
      decision,
    })
    await load(chat.id)
    if (result.status === "executed")
      toast(t("Action completed", "تم تنفيذ الإجراء"), "success")
    else if (result.status === "rejected")
      toast(t("Rejected. Nothing was changed.", "تم الرفض. لم يتم تغيير شيء."))
    else notice.textContent = result.text || proposalStatus(result.status)
